IF OBJECT_ID('dbo.Stores', 'U') IS NULL
BEGIN
  CREATE TABLE dbo.Stores (Id uniqueidentifier NOT NULL DEFAULT NEWID() PRIMARY KEY, Name nvarchar(150) NOT NULL, Address nvarchar(300) NULL, Timezone nvarchar(60) NOT NULL DEFAULT N'Asia/Ho_Chi_Minh', CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
  CREATE TABLE dbo.Users (Id uniqueidentifier NOT NULL DEFAULT NEWID() PRIMARY KEY, StoreId uniqueidentifier NULL REFERENCES dbo.Stores(Id), FullName nvarchar(150) NOT NULL, Email nvarchar(255) NOT NULL UNIQUE, PasswordHash nvarchar(255) NOT NULL, Role nvarchar(20) NOT NULL CHECK(Role IN ('owner','manager','cashier','server','barista')), IsActive bit NOT NULL DEFAULT 1, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
  CREATE TABLE dbo.Areas (Id uniqueidentifier NOT NULL DEFAULT NEWID() PRIMARY KEY, StoreId uniqueidentifier NOT NULL REFERENCES dbo.Stores(Id), Name nvarchar(100) NOT NULL, Position int NOT NULL DEFAULT 0);
  CREATE TABLE dbo.DiningTables (Id uniqueidentifier NOT NULL DEFAULT NEWID() PRIMARY KEY, AreaId uniqueidentifier NOT NULL REFERENCES dbo.Areas(Id), Code nvarchar(30) NOT NULL, Seats tinyint NOT NULL CHECK(Seats > 0), Status nvarchar(20) NOT NULL DEFAULT 'available' CHECK(Status IN ('available','occupied','ordering','reserved','disabled')), PositionX int NOT NULL DEFAULT 0, PositionY int NOT NULL DEFAULT 0, CONSTRAINT UQ_TableCode UNIQUE(AreaId, Code));
  CREATE TABLE dbo.Categories (Id uniqueidentifier NOT NULL DEFAULT NEWID() PRIMARY KEY, StoreId uniqueidentifier NOT NULL REFERENCES dbo.Stores(Id), Name nvarchar(100) NOT NULL, Position int NOT NULL DEFAULT 0, IsActive bit NOT NULL DEFAULT 1);
  CREATE TABLE dbo.Products (Id uniqueidentifier NOT NULL DEFAULT NEWID() PRIMARY KEY, CategoryId uniqueidentifier NOT NULL REFERENCES dbo.Categories(Id), Name nvarchar(150) NOT NULL, SKU nvarchar(60) NULL, BasePrice int NOT NULL CHECK(BasePrice >= 0), ImageUrl nvarchar(500) NULL, IsActive bit NOT NULL DEFAULT 1, IsAvailable bit NOT NULL DEFAULT 1, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
  CREATE TABLE dbo.Orders (Id uniqueidentifier NOT NULL DEFAULT NEWID() PRIMARY KEY, StoreId uniqueidentifier NOT NULL REFERENCES dbo.Stores(Id), TableId uniqueidentifier NULL REFERENCES dbo.DiningTables(Id), OrderNumber bigint IDENTITY(1000,1) NOT NULL UNIQUE, Status nvarchar(20) NOT NULL DEFAULT 'draft' CHECK(Status IN ('draft','sent','preparing','ready','served','paid','cancelled')), GuestCount tinyint NOT NULL DEFAULT 1, Note nvarchar(500) NULL, Subtotal int NOT NULL DEFAULT 0, Discount int NOT NULL DEFAULT 0, Total int NOT NULL DEFAULT 0, OpenedBy uniqueidentifier NULL REFERENCES dbo.Users(Id), OpenedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), ClosedAt datetime2 NULL, BillRequestedAt datetime2 NULL);
  CREATE TABLE dbo.OrderItems (Id uniqueidentifier NOT NULL DEFAULT NEWID() PRIMARY KEY, OrderId uniqueidentifier NOT NULL REFERENCES dbo.Orders(Id), ProductId uniqueidentifier NULL REFERENCES dbo.Products(Id), ProductName nvarchar(150) NOT NULL, UnitPrice int NOT NULL, Quantity smallint NOT NULL CHECK(Quantity > 0), Note nvarchar(500) NULL, Status nvarchar(20) NOT NULL DEFAULT 'sent', CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
  CREATE TABLE dbo.Payments (Id uniqueidentifier NOT NULL DEFAULT NEWID() PRIMARY KEY, OrderId uniqueidentifier NOT NULL REFERENCES dbo.Orders(Id), Amount int NOT NULL CHECK(Amount > 0), Method nvarchar(20) NOT NULL CHECK(Method IN ('cash','bank_transfer','card','e_wallet')), Reference nvarchar(100) NULL, ReceivedBy uniqueidentifier NULL REFERENCES dbo.Users(Id), PaidAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
  CREATE TABLE dbo.Ingredients (Id uniqueidentifier NOT NULL DEFAULT NEWID() PRIMARY KEY, StoreId uniqueidentifier NOT NULL REFERENCES dbo.Stores(Id), Name nvarchar(150) NOT NULL, Unit nvarchar(30) NOT NULL, Quantity decimal(12,3) NOT NULL DEFAULT 0, ReorderLevel decimal(12,3) NOT NULL DEFAULT 0);
  CREATE TABLE dbo.StockMovements (Id uniqueidentifier NOT NULL DEFAULT NEWID() PRIMARY KEY, IngredientId uniqueidentifier NOT NULL REFERENCES dbo.Ingredients(Id), QuantityChange decimal(12,3) NOT NULL, Reason nvarchar(200) NOT NULL, CreatedBy uniqueidentifier NULL REFERENCES dbo.Users(Id), CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
  CREATE INDEX IX_Orders_StoreStatus ON dbo.Orders(StoreId, Status, OpenedAt DESC);
  CREATE INDEX IX_OrderItems_Order ON dbo.OrderItems(OrderId);
  INSERT dbo.Stores(Name, Address) VALUES(N'Roast & Root', N'Hồ Con Rùa, TP. Hồ Chí Minh');
  INSERT dbo.Areas(StoreId, Name, Position) SELECT TOP 1 Id, N'Khu vực trong nhà', 1 FROM dbo.Stores;
END
